  "revision_action": "strengthen",
  "supportive_card_ids": ["C02","C79","C96","C22","C01","C07","C37","C53","C56","C185","C284","C273","C271","C282","C275","C285"],
  "contradictory_card_ids": ["C21","C266","C286"],
  "prediction_basis_card_ids": ["C02","C79","C22","C01","C07","C37","C53","C56","C185","C284","C273","C282"],
  "claims": [
    {
      "claim": "Direct absolute oral bioavailability measurements for apocynin (<10% human, 2.8–8.3% rat), tetrabenazine (0.1–8.5% human), meptazinol (~9% human), and 2-methoxyestradiol (1–3%) are below 20%; the query combines their methoxy-phenol-ketone and methoxy-ketone-amine motifs.",
      "card_ids": ["C02","C79","C96","C22","C01","C07","C37","C53","C56"]
    },
    {
      "claim": "L6 hepatic metabolic-stability records show moderate-to-high intrinsic clearance for related morphinans (dextromethorphan HLM CLint 41–65 µL/min/mg and half-life 14–27 min; morphine hepatic clearance 26 mL/min and hepatocyte CLint 17–28 µL/min/10^6 cells), indicating first-pass metabolic liability in the same scaffold; the query's phenol, enol ether, and ketone are additional soft spots.",
      "card_ids": ["C284","C273","C271","C282","C275","C285"]
    },
    {
      "claim": "C185 shows high absorption (Fa=90%) can coexist with F=2% due to extensive hepatic metabolism, so L4/L5 high-permeability/no-efflux records do not override the low-F analogs.",
      "card_ids": ["C185"]
    },
    {
      "claim": "Codeine and hydrocodone show low clearance and high oral bioavailability, but they lack the query's phenol and enol ether/ketone, limiting transfer of that favorable class behavior.",
      "card_ids": ["C266","C286"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C284","C273","C271","C282","C275","C285"]
    }
  ],
  "evidence_gaps": [
    "No direct measured oral bioavailability for the query molecule.",
    "No L6 record matches the query's exact enol ether/ketone/phenol substitution.",
    "First-pass hydrolysis of the enol ether and glucuronidation/sulfation of the phenol are not directly quantified.",
    "Conflicting class behavior (codeine/oxycodone high F versus dextromethorphan/morphine lower F) is unresolved."
  ],
  "decision_summary": "L6 hepatic metabolic-stability records strengthen the low prediction by showing moderate-to-high intrinsic clearance for related morphinans and additional metabolic soft spots in the query; direct low-F analogs remain the most threshold-relevant evidence. Prediction remains low with moderate confidence."
}

